/* From Uiverse.io by JkHuger - Tags: switch */
.__UIV_SCOPE__ .label-check {
  display: none;
}

.__UIV_SCOPE__ .hamburger-label {
  width: 70px;
  height: 58px;
  display: block;
  cursor: pointer;
}

.__UIV_SCOPE__ .hamburger-label div {
  width: 70px;
  height: 6px;
  background-color: #fff;
  position: absolute;
}

.__UIV_SCOPE__ .line1 {
  transition: all .3s;
}

.__UIV_SCOPE__ .line2 {
  margin: 18px 0 0 0;
  transition: 0.3s;
}

.__UIV_SCOPE__ .line3 {
  margin: 36px 0 0 0;
  transition: 0.3s;
}

.__UIV_SCOPE__ #label-check:checked + .hamburger-label .line1 {
  transform: rotate(35deg) scaleX(.55) translate(39px, -4.5px);
  border-radius: 50px 50px 50px 0;
}

.__UIV_SCOPE__ #label-check:checked + .hamburger-label .line3 {
  transform: rotate(-35deg) scaleX(.55) translate(39px, 4.5px);
  border-radius: 0 50px 50px 50px;
}

.__UIV_SCOPE__ #label-check:checked + .hamburger-label .line2 {
  border-top-right-radius: 50px;
  border-bottom-right-radius: 50px;
  width: 45px;
}
